import{_ as a,o as n,a as p,b as c}from"./app.DKoEZOcr.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"reg矢量计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_vector_compute"},{"text":"寄存器数据搬入","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_data_load/reg_data_load"},{"text":"load","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_data_load/load"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/reg_vector_compute/reg_data_load/load.md","filePath":"api/SIMD-API/tensor_api/reg_vector_compute/reg_data_load/load.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"},{"level":3,"title":"正常搬入","slug":"正常搬入","link":"#正常搬入"},{"level":3,"title":"解交织搬入","slug":"解交织搬入","link":"#解交织搬入"}],"lastUpdated":1788319986000}'),e={name:"api/SIMD-API/tensor_api/reg_vector_compute/reg_data_load/load.md"};function l(d,s,t,o,i,r){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>load</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;tensor_api/experimental/arch/vector/reg_data_load.h&quot;</code>，命名空间为<code>asc::te::experimental</code>。</p><p><code>load</code>用于将Unified Buffer（UB）中的数据搬入<a href="../reg_tensor/reg_tensor.html">reg_tensor</a>。接口通过<code>load_sideband_mode</code>配置正常搬入、上采样、下采样、解压缩或解交织等数据排列方式。<code>deintlv</code>模式返回<code>reg_pair</code>，其他模式返回<code>reg_tensor</code>。</p><p>接口支持以下两种寻址方式：</p><ul><li>传入<code>coord</code>时，从<code>tensor.engine() + tensor.layout()(coord)</code>对应的元素开始搬入。</li><li>不传入<code>coord</code>时，从<code>tensor</code>起始位置开始搬入。</li></ul><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><ul><li><p>指定坐标：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">load_sideband_mode</span><span class="w"> </span><span class="n">sideband_mode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">load_sideband_mode</span><span class="o">::</span><span class="n">direct</span><span class="p">,</span>
<span class="w">          </span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="p">,</span>
<span class="w">          </span><span class="k">typename</span><span class="w"> </span><span class="nc">Coord</span><span class="o">&gt;</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">decltype</span><span class="p">(</span><span class="k">auto</span><span class="p">)</span><span class="w"> </span><span class="n">load</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">Tensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">tensor</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">Coord</span><span class="o">&amp;</span><span class="w"> </span><span class="n">coord</span><span class="p">)</span>
</code></pre></div></li><li><p>从Tensor起始位置搬入：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">load_sideband_mode</span><span class="w"> </span><span class="n">sideband_mode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">load_sideband_mode</span><span class="o">::</span><span class="n">direct</span><span class="p">,</span>
<span class="w">          </span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="o">&gt;</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">decltype</span><span class="p">(</span><span class="k">auto</span><span class="p">)</span><span class="w"> </span><span class="n">load</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">Tensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">tensor</span><span class="p">)</span>
</code></pre></div></li></ul><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td><code>sideband_mode</code></td><td>搬入模式，类型为<code>load_sideband_mode</code>，默认值为<code>load_sideband_mode::direct</code>。具体取值请参考<a href="#%E8%A1%A83-load_sideband_mode%E5%8F%82%E6%95%B0%E8%AF%B4%E6%98%8E">表3</a>。</td></tr><tr><td><code>Tensor</code></td><td>源Tensor类型，由函数实参自动推导。Tensor必须位于UB。</td></tr><tr><td><code>Coord</code></td><td>源Tensor的坐标类型，由函数实参自动推导。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td><code>tensor</code></td><td>输入</td><td>源Tensor，必须位于UB。</td></tr><tr><td><code>coord</code></td><td>输入</td><td>搬入起始元素在<code>tensor</code>逻辑布局中的坐标。</td></tr></tbody></table><p><a id="表3-load_sideband_mode参数说明"></a></p><p><strong>表3</strong> <code>load_sideband_mode</code>参数说明</p><table><thead><tr><th>取值</th><th>含义</th><th>搬入起始地址对齐约束（Byte）</th></tr></thead><tbody><tr><td><code>load_sideband_mode::direct</code></td><td>正常模式，从UB连续读取VL数据量并搬入一个<code>reg_tensor</code>。</td><td>32</td></tr><tr><td><code>load_sideband_mode::deintlv</code></td><td>解交织模式，从UB连续读取2*VL数据量，将偶数索引和奇数索引的元素分别搬入返回值的<code>first</code>和<code>second</code>成员。</td><td>32</td></tr><tr><td><code>load_sideband_mode::downsample</code></td><td>2倍下采样模式，从UB读取2*VL数据量，每隔一个元素保留一个元素，得到VL数据量。</td><td>32</td></tr><tr><td><code>load_sideband_mode::unpack</code></td><td>2倍展开模式，从UB读取VL/2数据量，在每个源元素后补一个0，展开为VL数据量。</td><td>min(32, VL/2)</td></tr><tr><td><code>load_sideband_mode::unpack4</code></td><td>4倍展开模式，从UB读取VL/4数据量，在每个源元素后补三个0，展开为VL数据量。</td><td>min(32, VL/4)</td></tr><tr><td><code>load_sideband_mode::upsample</code></td><td>2倍上采样模式，从UB读取VL/2数据量，每个源元素在目的寄存器中重复两次。</td><td>min(32, VL/2)</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>Tensor元素类型与寄存器元素类型保持一致。不同模式支持的数据类型如下，未列出的类型或模式组合会产生编译期错误。</p><table><thead><tr><th><code>sideband_mode</code></th><th>支持的数据类型</th></tr></thead><tbody><tr><td><code>direct</code></td><td><code>int8_t</code>、<code>uint8_t</code>、<code>int16_t</code>、<code>uint16_t</code>、<code>int32_t</code>、<code>uint32_t</code>、<code>int64_t</code>、<code>uint64_t</code>、<code>half</code>、<code>bfloat16_t</code>、<code>float</code>、<code>hifloat8_t</code>、<code>fp8_e4m3fn_t</code>、<code>fp8_e5m2_t</code>、<code>fp8_e8m0_t</code>、<code>int4x2_t</code>、<code>fp4x2_e2m1_t</code>、<code>fp4x2_e1m2_t</code></td></tr><tr><td><code>deintlv</code></td><td><code>int8_t</code>、<code>uint8_t</code>、<code>int16_t</code>、<code>uint16_t</code>、<code>int32_t</code>、<code>uint32_t</code>、<code>half</code>、<code>bfloat16_t</code>、<code>float</code>、<code>hifloat8_t</code>、<code>fp8_e4m3fn_t</code>、<code>fp8_e5m2_t</code>、<code>fp8_e8m0_t</code>、<code>int4x2_t</code>、<code>fp4x2_e2m1_t</code>、<code>fp4x2_e1m2_t</code></td></tr><tr><td><code>downsample</code>、<code>upsample</code></td><td>8bit和16bit元素类型，包括对应位宽的整数、浮点和打包4bit类型</td></tr><tr><td><code>unpack</code></td><td>8bit、16bit和32bit元素类型，包括对应位宽的整数、浮点和打包4bit类型</td></tr><tr><td><code>unpack4</code></td><td>8bit元素类型，包括<code>int8_t</code>、<code>uint8_t</code>、<code>hifloat8_t</code>、三种FP8类型和三种打包4bit类型</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><ul><li><code>deintlv</code>模式返回<code>reg_pair&lt;typename Tensor::data_type&gt;</code>，其<code>first.reg</code>和<code>second.reg</code>分别保存偶数索引和奇数索引元素的搬入结果。</li><li>其他模式返回<code>reg_tensor&lt;typename Tensor::data_type&gt;</code>，其<code>reg</code>成员保存搬入结果。</li></ul><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>仅支持位于UB的Tensor。</li><li>搬入起始地址必须满足<a href="#%E8%A1%A83-load_sideband_mode%E5%8F%82%E6%95%B0%E8%AF%B4%E6%98%8E">表3</a>中的对齐约束。</li><li>传入<code>coord</code>时，坐标维数必须与Tensor布局匹配，且坐标不能越界。</li><li>搬入接口只初始化返回对象或目的对象的<code>reg</code>成员，不初始化<code>mask</code>成员。将结果用于读取<code>mask</code>的寄存器计算或<code>store</code>模式前，必须调用<code>with_mask</code>绑定有效mask。</li><li>寄存器数据搬入应在<code>__simd_vf__</code>函数或<code>__simd_callee__</code>函数中完成。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><h3 id="正常搬入">正常搬入<a class="header-anchor" href="#正常搬入">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/experimental/arch/vector/mask_reg_compute.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/experimental/arch/vector/reg_data_load.h&quot;</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">SrcTensor</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">LoadData</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">SrcTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load</span><span class="p">(</span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">0</span><span class="p">));</span>
<span class="w">    </span><span class="n">value</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">all_mask</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">());</span>
<span class="w">    </span><span class="c1">// 使用value完成后续寄存器计算。</span>
<span class="p">}</span>
</code></pre></div><h3 id="解交织搬入">解交织搬入<a class="header-anchor" href="#解交织搬入">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">SrcTensor</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">LoadDeinterleaved</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">SrcTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load_sideband_mode</span><span class="o">::</span><span class="n">deintlv</span><span class="o">&gt;</span><span class="p">(</span>
<span class="w">        </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">0</span><span class="p">));</span>

<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">all_mask</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">value</span><span class="p">.</span><span class="n">first</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="n">value</span><span class="p">.</span><span class="n">second</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// value.first和value.second分别保存偶数索引和奇数索引的元素。</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const m=a(e,[["render",l]]);export{h as __pageData,m as default};
